insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source, difficulty, concept_id) values ('che-ek-146', 'chemistry-electrochemistry-and-chemical-kinetics', 'chemistry', 'The notation $\mathrm{Pt}|\mathrm{Fe^{2+},Fe^{3+}}||\mathrm{Ag^+}|\mathrm{Ag}$ implies that the cell reaction is', '["$\\mathrm{Fe^{2+} + Ag^+ \\rightarrow Fe^{3+} + Ag}$","$\\mathrm{Fe^{3+} + Ag \\rightarrow Fe^{2+} + Ag^+}$","$\\mathrm{Fe^{2+} + Ag \\rightarrow Fe^{3+} + Ag^+}$","$\\mathrm{2Fe^{3+} + Ag^+ \\rightarrow 2Fe^{2+} + Ag}$"]'::jsonb, 0, 'Left-hand side is oxidised (Fe$^{2+} \to$ Fe$^{3+}$) and right-hand side is reduced (Ag$^+ \to$ Ag).', '[]'::jsonb, '{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"}'::jsonb, 'medium', 'cells-emf') on conflict (id) do update set stem = excluded.stem, options = excluded.options, answer_index = excluded.answer_index, explanation = excluded.explanation, images = excluded.images, source = excluded.source, difficulty = excluded.difficulty, concept_id = excluded.concept_id;
