insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source, difficulty, concept_id) values ('che-ek-150', 'chemistry-electrochemistry-and-chemical-kinetics', 'chemistry', 'Couples: $\mathrm{Ni^{2+}/Ni} = -0.25\ \mathrm{V}$, $\mathrm{Ag^+/Ag} = +0.80\ \mathrm{V}$. The spontaneous standard cell and its $E^\circ$ are', '["Ni anode, Ag cathode; $1.05\\ \\mathrm{V}$","Ag anode, Ni cathode; $1.05\\ \\mathrm{V}$","Ni anode, Ag cathode; $0.55\\ \\mathrm{V}$","Ag anode, Ni cathode; $0.55\\ \\mathrm{V}$"]'::jsonb, 0, 'Ni is the better reductant, so it is the anode. $E^\circ = 0.80 - (-0.25) = 1.05\ \mathrm{V}$.', '[]'::jsonb, '{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"}'::jsonb, 'hard', 'cells-emf') on conflict (id) do update set stem = excluded.stem, options = excluded.options, answer_index = excluded.answer_index, explanation = excluded.explanation, images = excluded.images, source = excluded.source, difficulty = excluded.difficulty, concept_id = excluded.concept_id;
